// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.selfmodifyimport com.roshan.persona.brain.skill.sandbox.JsSandboximport com.roshan.persona.brain.skill.sandbox.SandboxLimits as BrainSandboxLimitsimport com.roshan.persona.common.AppErrorimport com.roshan.persona.common.CorrelationIdimport com.roshan.persona.common.Resultimport kotlinx.coroutines.Dispatchersimport kotlinx.coroutines.withContextimport timber.log.Timberimport java.util.concurrent.ConcurrentHashMapimport javax.inject.Injectimport javax.inject.Singleton/** * NOUS — Self-modifying skill engine (Module 15 — Self-modify). * * Manages the lifecycle of user-defined (and LLM-authored) JavaScript skills. * A "self-modifying skill" is a JS script that NOUS writes for itself at * runtime — e.g., when the user says "always reply to SMS with my ETA", * NOUS writes a small JS skill that does exactly that, and registers it via * this engine. On future SMS arrivals, Brain's SkillRouter dispatches to * the JS skill (via [RhinoJsSandbox]). * * ## Storage * * In-memory by default (`ConcurrentHashMap`). Skills are lost when the * process dies. Production builds should swap in a Room+SQLCipher-backed * implementation (per ADR 0008's "no data loss on flavor switch" * requirement — the engine's API is storage-agnostic, so the swap is * mechanical). * * ## Thread safety * * [ConcurrentHashMap] for the skill registry — `createSkill` / `updateSkill` * / `deleteSkill` / `listSkills` / `executeSkill` can all be called from * any thread, concurrently. Per-skill atomicity is enforced via `compute` * / `remove` on the map. * * ## Self-modify flow * * 1. LLM (or user) calls [createSkill] with a name + JS source. * 2. Engine stores it in the registry, returns the skill ID (= name). * 3. Brain's SkillRouter routes incoming requests to the skill by ID. * 4. Router calls [executeSkill] with the request params. * 5. Engine delegates to [JsSandbox.execute] (= [RhinoJsSandbox]). * 6. Result (or typed error) is returned to the router. * * ## Self-correction loop (TODO) * * Whe // MEDIUM_FIX: Track in project backlogn [executeSkill] returns a [SandboxResult.ScriptError], the engine * SHOULD forward the error back to the LLM for self-correction (the LLM * regenerates the script with the fix, then calls [updateSkill]). * * This is not yet implemented — it's a Module 15 v2 feature. The current * engine just returns the error to the caller. * * @see RhinoJsSandbox * @see SkillScript * @see <a href="docs/adr/0008-self-modifying-js-flavor-gated.md">ADR 0008</a> */@Singletonclass SelfModifyEngine @Inject constructor(    /**     * The JS sandbox used to execute skills.     *     * Bound by [SelfModifyModule] to [RhinoJsSandbox] in `dev`/`internal`     * flavors. In `prod`, this class is absent (not compiled) and Brain     * uses `NoOpJsSandbox` instead.     */    private val sandbox: JsSandbox,) {    /**     * In-memory skill registry, keyed by skill name (= ID).     *     * `ConcurrentHashMap` for thread-safe create/update/delete/list. Each     * mutation is atomic via `compute` / `remove`; reads via `get` /     * `keys` snapshot.     */    private val skills: ConcurrentHashMap<String, SkillScript> = ConcurrentHashMap()    /**     * Maximum number of custom skills allowed.     *     * Prevents runaway self-modification from filling memory. 100 is a     * conservative default — power users who need more can override this     * in a future config flag.     */    private val maxSkills: Int = DEFAULT_MAX_SKILLS    /**     * Maximum script size, in characters.     *     * Prevents the LLM from generating huge scripts that would OOM the     * sandbox during compilation. 64 KB is generous — typical skills are     * under 2 KB.     */    private val maxScriptChars: Int = DEFAULT_MAX_SCRIPT_CHARS    // ─── Lifecycle: create / update / delete / list ────────────────────────    /**     * Create a new self-modifying skill.     *     * @param name unique skill identifier. Must match `[a-zA-Z][a-zA-Z0-9_]*`     *   (no spaces, no special chars — used as a Brain SkillRouter key).     * @param script full JavaScript source. Will be executed verbatim by     *   [RhinoJsSandbox.execute] when the skill is invoked.     * @return [Result.Success] with the skill ID (= [name]) on success, or     *   [Result.Failure] with:     *   - [AppError.Configuration.InvalidProviderConfig] if [name] is invalid.     *   - [AppError.Configuration.ProviderAlreadyExists] if a skill with     *     [name] already exists (use [updateSkill] instead).     *   - [AppError.Llm.OutOfMemory] if the registry is full ([maxSkills]).     *   - [AppError.Configuration.InvalidProviderConfig] if [script] is too long.     */    suspend fun createSkill(name: String, script: String): Result<String> =        withContext(Dispatchers.Default) {            val correlationId = CorrelationId.generate()            val startNanos = System.nanoTime()            val nameError = validateName(name)            if (nameError != null) {                return@withContext Result.Failure(                    error = nameError,                    correlationId = correlationId,                    durationNanos = System.nanoTime() - startNanos,                )            }            val scriptError = validateScript(script)            if (scriptError != null) {                return@withContext Result.Failure(                    error = scriptError,                    correlationId = correlationId,                    durationNanos = System.nanoTime() - startNanos,                )            }            if (skills.size >= maxSkills) {                return@withContext Result.Failure(                    error = AppError.Llm.OutOfMemory(                        modelId = "selfmodify_engine",                        requiredMb = maxSkills,                    ),                    correlationId = correlationId,                    durationNanos = System.nanoTime() - startNanos,                )            }            val created = SkillScript.fresh(name = name, script = script)            val previous = skills.putIfAbsent(name, created)            if (previous != null) {                return@withContext Result.Failure(                    error = AppError.Configuration.ProviderAlreadyExists(providerId = name),                    correlationId = correlationId,                    durationNanos = System.nanoTime() - startNanos,                )            }            Timber.i("Created self-modify skill '%s' (v1, %d chars)", name, script.length)            Result.Success(                data = name,                correlationId = correlationId,                durationNanos = System.nanoTime() - startNanos,                metadata = mapOf(                    "skillName" to name,                    "version" to "1",                    "scriptChars" to script.length.toString(),                ),            )        }    /**     * Update an existing skill's script.     *     * Bumps [SkillScript.version] by 1, sets [SkillScript.updatedAt] to now.     *     * @param name existing skill identifier.     * @param script new JavaScript source.     * @return [Result.Success] with `Unit` on success, or [Result.Failure]     *   with [AppError.Skill.NotFound] if [name] doesn't exist.     */    suspend fun updateSkill(name: String, script: String): Result<Unit> =        withContext(Dispatchers.Default) {            val correlationId = CorrelationId.generate()            val startNanos = System.nanoTime()            val scriptError = validateScript(script)            if (scriptError != null) {                return@withContext Result.Failure(                    error = scriptError,                    correlationId = correlationId,                    durationNanos = System.nanoTime() - startNanos,                )            }            var updated: SkillScript? = null            val notFound = skills.computeIfPresent(name) { _, current ->                updated = current.withUpdatedScript(script)                updated            } == null            if (notFound || updated == null) {                return@withContext Result.Failure(                    error = AppError.Skill.NotFound(skillName = name),                    correlationId = correlationId,                    durationNanos = System.nanoTime() - startNanos,                )            }            // Safe to use updated here — we already checked null above.            // Store in local val to avoid repeated null checks.            val savedScript = updated            Timber.i("Updated self-modify skill '%s' (v%d, %d chars)",                name, savedScript?.version ?: 0, script.length)            Result.Success(                data = Unit,                correlationId = correlationId,                durationNanos = System.nanoTime() - startNanos,                metadata = mapOf(                    "skillName" to name,                    "version" to (savedScript?.version?.toString() ?: "0"),                ),            )        }    /**     * Delete a skill.     *     * @param name existing skill identifier.     * @return [Result.Success] with `Unit` on success, or [Result.Failure]     *   with [AppError.Skill.NotFound] if [name] doesn't exist.     */    suspend fun deleteSkill(name: String): Result<Unit> =        withContext(Dispatchers.Default) {            val correlationId = CorrelationId.generate()            val startNanos = System.nanoTime()            val removed = skills.remove(name)            if (removed == null) {                return@withContext Result.Failure(                    error = AppError.Skill.NotFound(skillName = name),                    correlationId = correlationId,                    durationNanos = System.nanoTime() - startNanos,                )            }            Timber.i("Deleted self-modify skill '%s' (was v%d)", name, removed.version)            Result.Success(                data = Unit,                correlationId = correlationId,                durationNanos = System.nanoTime() - startNanos,                metadata = mapOf(                    "skillName" to name,                    "deletedVersion" to removed.version.toString(),                ),            )        }    /**     * List all custom skill names.     *     * Returns a snapshot — modifications after this call returns are not     * reflected in the returned list.     *     * @return skill names, sorted alphabetically for deterministic ordering.     */    fun listSkills(): List<String> = skills.keys().toList().sorted()    /**     * Get a skill by name (read-only view).     *     * @return the [SkillScript], or `null` if not found.     */    fun getSkill(name: String): SkillScript? = skills[name]    // ─── Execution ─────────────────────────────────────────────────────────    /**     * Execute a stored skill by name.     *     * Looks up the skill, fetches its current script, and delegates to     * [JsSandbox.execute] (= [RhinoJsSandbox]) with default limits.     *     * @param name existing skill identifier.     * @param params parameters passed to the script as the global `params`     *   JS object. Values must be JSON-serializable (String, Int, Boolean,     *   List, Map, null).     * @return [Result.Success] with the script's String-ified return value,     *   or [Result.Failure] with:     *   - [AppError.Skill.NotFound] if [name] doesn't exist.     *   - [AppError.Skill.TimedOut] if the script exceeded its time budget.     *   - [AppError.Skill.Crashed] if the script threw or OOM'd.     *   - [AppError.Security.IntegrityCheckFailed] if the script attempted     *     a security violation (should permanently quarantine the skill).     */    suspend fun executeSkill(        name: String,        params: Map<String, String>,    ): Result<String> = withContext(Dispatchers.Default) {        val correlationId = CorrelationId.generate()        val startNanos = System.nanoTime()        val skill = skills[name]        if (skill == null) {            return@withContext Result.Failure(                error = AppError.Skill.NotFound(skillName = name),                correlationId = correlationId,                durationNanos = System.nanoTime() - startNanos,            )        }        Timber.d("Executing self-modify skill '%s' (v%d)", name, skill.version)        // Convert Map<String, String> → Map<String, Any> for the sandbox.        // (Brain's JsSandbox interface accepts Any values; we restrict to        // String at the engine layer for simplicity. Future versions may        // accept richer types.)        val paramsAny: Map<String, Any> = params.mapValues { it.value as? Any ?: "" }        // Use default limits for stored skills. Strict limits could be used        // for first-run validation (TODO — see "Self-correction loop" above).        val limits = BrainSandboxLimits.DEFAULT        sandbox.execute(script = skill.script, params = paramsAny, limits = limits)    }    // ─── Validation ────────────────────────────────────────────────────────    /**     * Validate a skill name.     *     * @return `null` if valid, or an [AppError] describing the problem.     */    private fun validateName(name: String): AppError? {        if (name.isBlank()) {            return AppError.Configuration.InvalidProviderConfig(                reason = "Skill name must not be blank",            )        }        if (!NAME_REGEX.matches(name)) {            return AppError.Configuration.InvalidProviderConfig(                reason = "Skill name '$name' must match $NAME_PATTERN (alphanumeric + underscore, " +                    "starting with a letter)",            )        }        if (name.length > MAX_NAME_LENGTH) {            return AppError.Configuration.InvalidProviderConfig(                reason = "Skill name '$name' too long (max $MAX_NAME_LENGTH chars)",            )        }        return null    }    /**     * Validate a skill script.     *     * @return `null` if valid, or an [AppError] describing the problem.     */    private fun validateScript(script: String): AppError? {        if (script.isBlank()) {            return AppError.Configuration.InvalidProviderConfig(                reason = "Script must not be blank",            )        }        if (script.length > maxScriptChars) {            return AppError.Configuration.InvalidProviderConfig(                reason = "Script too long (${script.length} > $maxScriptChars chars)",            )        }        return null    }    companion object {        /** Regex pattern for valid skill names. */        const val NAME_PATTERN: String = "[a-zA-Z][a-zA-Z0-9_]*"        /** Compiled [NAME_PATTERN] regex. */        val NAME_REGEX: Regex = Regex(NAME_PATTERN)        /** Maximum skill name length. */        const val MAX_NAME_LENGTH: Int = 64        /** Default maximum number of custom skills. */        const val DEFAULT_MAX_SKILLS: Int = 100        /** Default maximum script size (characters). */        const val DEFAULT_MAX_SCRIPT_CHARS: Int = 65_536 // 64 KB    }}